const API = ''
type RecordShape = Record<string, any>
type ViewKey = 'overview' | 'smart' | 'keywords' | 'videos' | 'leads' | 'agents' | 'tasks' | 'analytics' | 'providers' | 'settings'

const navigation: Array<{ key: ViewKey; label: string; icon: LucideIcon; section?: string }> = [
  { key: 'overview', label: '总览', icon: LayoutDashboard },
  { key: 'smart', label: '智能截流', icon: Sparkles },
  { key: 'keywords', label: '关键词雷达', icon: Radar },
  { key: 'videos', label: '热门视频', icon: Video },
  { key: 'leads', label: '潜客池', icon: Target },
  { key: 'agents', label: '智能体', icon: Bot, section: '系统' },
  { key: 'tasks', label: '任务中心', icon: ListChecks },
  { key: 'analytics', label: '数据分析', icon: BarChart3 },
  { key: 'providers', label: '数据源', icon: Database, section: '配置' },
  { key: 'settings', label: '系统设置', icon: Settings },
]

async function request(path: string, options?: RequestInit) {
  const headers = new Headers(options?.headers)
  headers.set('Content-Type', 'application/json')
  const response = await fetch(`${API}${path}`, { ...options, headers })
  if (!response.ok) throw new Error((await response.json().catch(() => ({}))).detail || `请求失败 ${response.status}`)
  return response.json()
}

const demoLeads = Array.from({ length: 8 }, (_, index) => ({ id: index + 1, nickname: ['装修小白', '想翻新的阿敏', '长沙业主老周', '望城小何', '小满准备装修', '被增项坑过', '岳麓新家', '预算15万'][index], lead_score: [97, 96, 94, 92, 90, 88, 86, 82][index], lead_level: index < 3 ? 'S' : index < 6 ? 'A' : 'B', need: '旧房翻新 / 全屋装修', location: '长沙', budget: index % 3 ? '15万' : '待确认', purchase_stage: '比较方案', occurrence_count: index % 4 + 1, content: ['长沙有没有靠谱一点的？', '我家120平，15万能下来吗？', '旧房翻新大概多少钱？'][index % 3] }))
const demoKeywords = ['长沙装修多少钱', '长沙装修哪家好', '旧房翻新避坑', '120平装修预算', '有没有靠谱装修公司', '装修增项怎么办', '长沙全屋定制', '准备装修怎么选公司'].map((keyword, index) => ({ keyword, category: ['购买意向', '问题词', '避坑词', '价格词'][index % 4], opportunity_score: 97 - index, commercial_score: 84 + index, lead_count: 36 - index * 2, video_count: 12 - index, comment_count: 138 - index * 7 }))
const demoVideos = Array.from({ length: 6 }, (_, index) => ({ id: index + 1, title: ['长沙装修最容易踩的 8 个坑', '120 平米装修预算怎么分配？', '旧房翻新前一定要看这条'][index % 3], creator: `长沙装修观察员${index + 1}`, likes: 12800 - index * 850, comments: 486 - index * 31, opportunity_score: 96 - index * 2, level: index < 2 ? 'A' : 'B', keyword: '长沙装修避坑' }))

export default function Page() {
  const [view, setView] = useState<ViewKey>('overview')
  const [project, setProject] = useState<RecordShape>({ id: 1, name: '长沙装修', industry: '装修', location: '长沙' })
  const [projects, setProjects] = useState<RecordShape[]>([])
  const [collapsed, setCollapsed] = useState(false)
  const [dark, setDark] = useState(false)
  const [mobileNav, setMobileNav] = useState(false)

  useEffect(() => {
    const savedView = window.location.hash.replace('#', '') as ViewKey
    if (navigation.some((item) => item.key === savedView)) setView(savedView)
    request('/api/projects').then((items) => { setProjects(items); if (items[0]) setProject(items[0]) }).catch(() => {})
  }, [])
  useEffect(() => { document.documentElement.dataset.theme = dark ? 'dark' : 'light' }, [dark])
  function navigate(next: ViewKey) { setView(next); window.history.replaceState(null, '', `#${next}`); setMobileNav(false) }
  return <div className="product-shell"><Sidebar view={view} navigate={navigate} collapsed={collapsed} setCollapsed={setCollapsed} mobileNav={mobileNav} setMobileNav={setMobileNav} project={project} projects={projects} setProject={setProject} /><main className="workspace"><Topbar view={view} dark={dark} setDark={setDark} setMobileNav={setMobileNav} project={project} /><div className="workspace-scroll"><ViewRouter view={view} project={project} navigate={navigate} /></div></main></div>
}

function Sidebar({ view, navigate, collapsed, setCollapsed, mobileNav, setMobileNav, project, projects, setProject }: RecordShape) {
  return <><div className={`mobile-overlay ${mobileNav ? 'show' : ''}`} onClick={() => setMobileNav(false)} /><aside className={`sidebar ${collapsed ? 'collapsed' : ''} ${mobileNav ? 'mobile-open' : ''}`}><div className="sidebar-top"><div className="wordmark"><span className="wordmark-mark"><Radar size={16} /></span><span className="wordmark-text">AI 截流雷达<small>LEAD RADAR</small></span></div><button className="rail-button close-mobile" onClick={() => setMobileNav(false)}><X size={17} /></button><button className="rail-button collapse-button" onClick={() => setCollapsed(!collapsed)}>{collapsed ? <PanelLeftOpen size={16} /> : <PanelLeftClose size={16} />}</button></div><div className="workspace-switcher"><div className="switcher-label">工作区</div><button className="switcher-button"><span className="project-seal">{(project?.name || '长')[0]}</span><span className="switcher-name">{project?.name || '长沙装修'}<small>个人工作区</small></span><ChevronDown size={14} /></button>{projects.length > 1 && <select className="project-select-hidden" value={project.id} onChange={(event) => setProject(projects.find((item: RecordShape) => item.id === Number(event.target.value)))}>{projects.map((item: RecordShape) => <option key={item.id} value={item.id}>{item.name}</option>)}</select>}</div><nav className="side-nav">{navigation.map((item, index) => <div key={item.key}>{item.section && <div className="nav-section">{item.section}</div>}<button className={`nav-link ${view === item.key ? 'active' : ''}`} onClick={() => navigate(item.key)}><item.icon size={17} strokeWidth={1.8} /><span>{item.label}</span>{item.key === 'leads' && <span className="nav-badge">50</span>}</button></div>)}</nav><div className="sidebar-bottom"><div className="provider-state"><span className="status-dot" /><span>数据源已配置</span><MoreHorizontal size={15} /></div><div className="account-row"><div className="account-avatar">L</div><div><b>本地工作区</b><small>Windows · 本地运行</small></div><CircleHelp size={15} /></div></div></aside></>
}

function Topbar({ view, dark, setDark, setMobileNav, project }: RecordShape) {
  const label = navigation.find((item) => item.key === view)?.label || '总览'
  return <header className="topbar"><div className="topbar-left"><button className="mobile-menu" onClick={() => setMobileNav(true)}><Menu size={18} /></button><span className="top-context">工作区</span><ChevronRight size={14} className="top-chevron" /><span className="top-current">{label}</span></div><div className="topbar-right"><div className="runtime-chip"><span className="status-dot" />实时监控中</div><button className="top-icon-button" aria-label="搜索"><Search size={17} /></button><button className="top-icon-button" onClick={() => setDark(!dark)} aria-label="切换主题">{dark ? <Sun size={17} /> : <Moon size={17} />}</button><div className="top-profile">L</div></div></header>
}

function ViewRouter({ view, project, navigate }: RecordShape) {
  if (view === 'smart') return <SmartViewLive project={project} navigate={navigate} />
  if (view === 'keywords') return <KeywordsViewLive project={project} />
  if (view === 'videos') return <VideosViewLive project={project} />
  if (view === 'leads') return <LeadsView project={project} navigate={navigate} />
  if (view === 'agents') return <AgentsView />
  if (view === 'tasks') return <TasksView project={project} />
  if (view === 'analytics') return <AnalyticsView project={project} />
  if (view === 'providers') return <ProvidersView />
  if (view === 'settings') return <SettingsView project={project} />
  return <DashboardLive project={project} navigate={navigate} />
}

function SmartViewLive({ project, navigate }: RecordShape) {
  const [form, setForm] = useState({ name: '我的行业雷达', industry: project.industry || '', location: project.location || '', service: '', price_range: '', target_customer: '', description: '' })
  const [provider, setProvider] = useState('加载中…')
  const [stage, setStage] = useState('')
  const [result, setResult] = useState<RecordShape>()
  const [error, setError] = useState('')
  useEffect(() => { request('/api/settings').then((settings) => setProvider(settings.content_provider === 'mock' ? 'Mock Provider' : settings.content_provider || '未配置')).catch(() => setProvider('状态未知')) }, [])
  const set = (key: string, value: string) => setForm((current) => ({ ...current, [key]: value }))
  async function activate() {
    setError(''); setStage('creating')
    try { const created = await request('/api/projects', { method: 'POST', body: JSON.stringify(form) }); setStage('analyzing'); const analysis = await request(`/api/projects/${created.id}/smart-mode`, { method: 'POST' }); setResult(analysis); setStage('scanning'); await request(`/api/projects/${created.id}/scan`, { method: 'POST' }); setStage('done'); navigate('tasks') } catch (err: any) { setError(err.message); setStage('') }
  }
  return <div className="page"><PageHeader eyebrow="INDUSTRY INTELLIGENCE" title="智能截流" description="描述你的业务，系统会生成搜索策略并开始监听公开需求。" actions={<div className="provider-chip"><span className="status-dot" />{provider}</div>} />{error && <div className="error-banner"><X size={15} />{error}</div>}<div className="smart-grid"><section className="panel form-panel"><PanelHeader label="PROJECT BRIEF" title="业务画像" action={<span className="required-note">* 必填信息</span>} /><div className="form-grid"><Field label="项目名称" value={form.name} onChange={(value: string) => set('name', value)} placeholder="我的行业雷达" /><Field label="行业" value={form.industry} onChange={(value: string) => set('industry', value)} placeholder="装修、教育、财税" /><Field label="地区" value={form.location} onChange={(value: string) => set('location', value)} placeholder="例如：长沙" /><Field label="业务 / 产品服务" wide value={form.service} onChange={(value: string) => set('service', value)} placeholder="你具体提供什么服务？" /><Field label="客单价" value={form.price_range} onChange={(value: string) => set('price_range', value)} placeholder="例如：5万-30万" /><Field label="目标客户" wide value={form.target_customer} onChange={(value: string) => set('target_customer', value)} placeholder="谁最可能购买？" /><Field label="补充介绍" wide area value={form.description} onChange={(value: string) => set('description', value)} placeholder="优势、客户痛点、服务限制…" /></div><div className="form-actions"><Button variant="accent" icon={Sparkles} onClick={activate} disabled={!!stage && stage !== 'done'}>{stage === 'done' ? '雷达已开启' : stage ? '处理中…' : '分析并开启智能模式'}</Button><span className="form-footnote"><Check size={13} />仅处理公开内容，不自动发送消息</span></div></section><section className="panel workflow-panel"><PanelHeader label="AUTOMATION PLAN" title="系统将自动完成" /><div className="workflow-list">{['理解行业与客户语言', '生成高意图关键词', '发现并排序机会视频', '分析公开评论信号', '归档潜客并生成建议'].map((label, index) => <div className={`workflow-row ${stage === 'done' || (stage && index < 2) ? 'complete' : ''}`} key={label}><span>{stage === 'done' || (stage && index < 2) ? <Check size={13} /> : String(index + 1).padStart(2, '0')}</span><b>{label}</b></div>)}</div>{result ? <div className="analysis-summary"><div className="summary-number">{result.keyword_count}</div><div><b>个行业关键词已生成</b><span>高机会词将优先进入扫描队列</span></div></div> : <div className="workflow-note"><BrainIcon /><b>准备好后，系统会持续工作</b><span>扫描完成后，你可以在任务中心查看进度和失败重试。</span></div>}</section></div></div>
}

function PageHeader({ eyebrow, title, description, actions }: RecordShape) { return <div className="page-header"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{description && <p>{description}</p>}</div>{actions && <div className="header-actions">{actions}</div>}</div> }
function Button({ children, variant = 'secondary', icon: Icon, onClick, disabled }: RecordShape) { return <button className={`button button-${variant}`} onClick={onClick} disabled={disabled}>{Icon && <Icon size={15} strokeWidth={1.8} />}{children}</button> }
function StatusPill({ children, tone = 'neutral' }: RecordShape) { return <span className={`status-pill ${tone}`}>{children}</span> }
function SectionLabel({ children }: RecordShape) { return <div className="section-label">{children}</div> }
function Skeleton({ width = '100%' }: { width?: string }) { return <span className="skeleton" style={{ width }} /> }

function DashboardLive({ project, navigate }: RecordShape) {
  const [data, setData] = useState<RecordShape>({ stats: {}, events: [], checklist: { done: 0, total: 6 } })
  const [error, setError] = useState('')
  const [live, setLive] = useState<RecordShape[]>([])
  useEffect(() => { request(`/api/dashboard?project_id=${project.id}`).then(setData).catch((err) => setError(err.message)) }, [project.id])
  useEffect(() => { const source = new EventSource(`/api/events/stream?project_id=${project.id}`); source.onmessage = (event) => { try { setLive((current) => [...current.slice(-7), JSON.parse(event.data)]) } catch {} }; return () => source.close() }, [project.id])
  const stats = data.stats || {}
  const events = [...(data.events || []), ...live].slice(-8)
  const topKeywords = data.top_keywords || []
  const projectName = `${project.location || '未设置地区'} · ${project.industry || '未设置行业'}`
  const done = Number(data.checklist?.done || 0)
  return <div className="page"><PageHeader eyebrow="OPERATIONS / LIVE" title="总览" description="把公开内容里的购买信号，变成今天可以行动的客户队列。" actions={<><Button icon={RefreshCw} onClick={() => window.location.reload()}>刷新数据</Button><Button variant="accent" icon={Sparkles} onClick={() => navigate('smart')}>开启智能截流</Button></>} />{error && <div className="error-banner"><X size={15} />{error}</div>}<div className="context-bar"><div className="context-main"><span className="context-mark"><Radar size={17} /></span><div><b>{projectName} 行业雷达</b><span>当前使用 {data.mode || '文本数据源'} · 所有判断只基于文字与结构化字段</span></div></div><div className="context-meta"><span><span className="status-dot" />运行中</span><span className="context-divider" /><span>数据实时更新</span></div></div><div className="metric-grid"><Metric label="扫描关键词" value={stats.keywords ?? <Skeleton width="36px" />} helper="当前项目" trend="" icon={Radar} /><Metric label="发现视频" value={stats.videos ?? <Skeleton width="36px" />} helper="当前项目" trend="" icon={Video} /><Metric label="公开评论" value={stats.comments ?? <Skeleton width="50px" />} helper="公开文本" trend="" icon={MessageCircle} /><Metric label="新增潜客" value={stats.leads ?? <Skeleton width="36px" />} helper={`${stats.s_leads || 0} 个 S 级机会`} trend="" icon={Target} accent /></div><div className="dashboard-grid"><section className="panel feed-panel"><PanelHeader label="LIVE SIGNAL FEED" title="实时截流雷达" action={<StatusPill tone="live"><span className="status-dot" />正在监听</StatusPill>} /><div className="feed-list">{events.length ? events.map((event: RecordShape, index: number) => <div className="feed-item" key={`${event.id || 'live'}-${index}`}><time>{formatTime(event.created_at)}</time><span className={`feed-marker ${event.event_type?.includes('lead') ? 'hot' : ''}`} /><div className="feed-copy"><b>{event.message}</b>{event.payload?.keyword && <span>关键词 · {event.payload.keyword}</span>}</div>{event.event_type === 'task.completed' && <Check size={15} className="feed-check" />}</div>) : <EmptyState icon={Activity} text="启动一次智能扫描，实时事件会出现在这里。" action={{ label: '开启扫描', onClick: () => navigate('smart') }} />}</div><div className="panel-footer-link" onClick={() => navigate('tasks')}>查看任务事件 <ArrowUpRight size={14} /></div></section><section className="panel signal-panel"><PanelHeader label="SIGNAL QUALITY" title="机会信号" action={<button className="icon-button"><MoreHorizontal size={16} /></button>} /><div className="signal-total"><div><b>{stats.s_leads || 0}</b><span>S 级潜客</span></div><div className="signal-ring"><span>—</span><small>基于真实数据</small></div></div><div className="signal-bars"><SignalBar label="明确询价" value={stats.lead_signal_rate || 0} color="red" /><SignalBar label="预算表达" value={stats.budget_signal_rate || 0} color="dark" /><SignalBar label="本地需求" value={stats.location_signal_rate || 0} color="gray" /></div><div className="insight-line"><Zap size={14} /><span>信号趋势：<b>以实际扫描结果为准</b></span></div></section></div><div className="lower-grid"><section className="panel table-panel compact-table"><PanelHeader label="TOP OPPORTUNITIES" title="最值得扫描的词" action={<button className="text-button" onClick={() => navigate('keywords')}>查看全部 <ArrowUpRight size={13} /></button>} /><table><thead><tr><th>关键词</th><th>机会评分</th><th>潜客</th><th>最近扫描</th></tr></thead><tbody>{topKeywords.length ? topKeywords.slice(0, 4).map((item: RecordShape) => <tr key={item.id || item.keyword}><td><b>{item.keyword}</b><small>{item.category} · AI 推荐</small></td><td><span className="score-value">{Math.round(item.opportunity_score || 0)}</span></td><td><b className="accent-text">{item.lead_count || 0}</b></td><td className="muted">{formatDateTime(item.last_scanned_at)}</td></tr>) : <tr><td colSpan={4}><EmptyState icon={Radar} text="完成一次扫描后，机会词会出现在这里。" /></td></tr>}</tbody></table></section><section className="panel checklist-panel"><PanelHeader label="TODAY" title="工作进度" action={<StatusPill tone="neutral">{done} / 6</StatusPill>} /><div className="checklist"><CheckRow label="理解行业与目标客户" done={Boolean(project.intelligence && Object.keys(project.intelligence).length)} /><CheckRow label="生成关键词雷达" done={Number(stats.keywords) > 0} /><CheckRow label="扫描公开内容" done={Number(stats.videos) > 0} /><CheckRow label="判断购买意向" done={Number(stats.leads) > 0} /><CheckRow label="人工跟进高价值潜客" /><CheckRow label="回填成交结果" /></div></section></div></div>
}
function Metric({ label, value, helper, trend, icon: Icon, accent }: RecordShape) { return <div className="metric"><div className="metric-label"><span>{label}</span><Icon size={15} /></div><div className="metric-value">{value}</div><div className="metric-foot"><span>{helper}</span><b className={accent ? 'positive' : ''}><ArrowUpRight size={12} />{trend}</b></div></div> }
function PanelHeader({ label, title, action }: RecordShape) { return <div className="panel-header"><div><SectionLabel>{label}</SectionLabel><h2>{title}</h2></div>{action}</div> }
function SignalBar({ label, value, color }: RecordShape) { return <div className="signal-bar"><div><span>{label}</span><b>{value}%</b></div><i><em className={color} style={{ width: `${value}%` }} /></i></div> }
function CheckRow({ label, done }: RecordShape) { return <div className={`check-row ${done ? 'done' : ''}`}><span className="check-box">{done && <Check size={12} />}</span><span>{label}</span>{done ? <small>完成</small> : <small className="next-label">待处理</small>}</div> }
function EmptyState({ icon: Icon, text, action }: RecordShape) { return <div className="empty-state"><Icon size={22} /><span>{text}</span>{action && <button onClick={action.onClick}>{action.label} <ArrowUpRight size={13} /></button>}</div> }
function formatTime(value?: string) { return value ? new Date(value).toLocaleTimeString('zh-CN', { hour12: false }) : '--:--' }
function formatDateTime(value?: string | null) { return value ? new Date(value).toLocaleString('zh-CN', { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : '未安排' }
function downloadJson(filename: string, value: unknown) { const blob = new Blob([JSON.stringify(value, null, 2)], { type: 'application/json;charset=utf-8' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = filename; link.click(); URL.revokeObjectURL(url) }

function SmartView({ project, navigate }: RecordShape) { const [form, setForm] = useState({ name: '我的行业雷达', industry: project.industry || '装修', location: project.location || '长沙', service: '旧房翻新 / 全屋装修', price_range: '5万-30万', target_customer: '准备装修的长沙业主', description: '提供设计、施工与预算建议。' }); const [stage, setStage] = useState(''); const [result, setResult] = useState<RecordShape>(); const [error, setError] = useState(''); const set = (key: string, value: string) => setForm((current) => ({ ...current, [key]: value }))
  async function activate() { setError(''); setStage('creating'); try { const created = await request('/api/projects', { method: 'POST', body: JSON.stringify(form) }); setStage('analyzing'); const analysis = await request(`/api/projects/${created.id}/smart-mode`, { method: 'POST' }); setResult(analysis); setStage('scanning'); await request(`/api/projects/${created.id}/scan`, { method: 'POST' }); setStage('done') } catch (err: any) { setError(err.message); setStage('') } }
  return <div className="page"><PageHeader eyebrow="INDUSTRY INTELLIGENCE" title="智能截流" description="描述你的业务，系统会生成搜索策略并开始监听公开需求。" actions={<div className="provider-chip"><span className="status-dot" />Mock Provider</div>} /><div className="smart-grid"><section className="panel form-panel"><PanelHeader label="PROJECT BRIEF" title="业务画像" action={<span className="required-note">* 必填信息</span>} /><div className="form-grid"><Field label="行业" value={form.industry} onChange={(value: string) => set('industry', value)} placeholder="装修、教育、财税" /><Field label="地区" value={form.location} onChange={(value: string) => set('location', value)} placeholder="例如：长沙" /><Field label="业务 / 产品服务" wide value={form.service} onChange={(value: string) => set('service', value)} placeholder="你具体提供什么服务？" /><Field label="客单价" value={form.price_range} onChange={(value: string) => set('price_range', value)} placeholder="例如：5万-30万" /><Field label="目标客户" wide value={form.target_customer} onChange={(value: string) => set('target_customer', value)} placeholder="谁最可能购买？" /><Field label="补充介绍" wide area value={form.description} onChange={(value: string) => set('description', value)} placeholder="优势、客户痛点、服务限制…" /></div>{error && <div className="error-inline"><X size={14} />{error}</div>}<div className="form-actions"><Button variant="accent" icon={Sparkles} onClick={activate} disabled={!!stage && stage !== 'done'}>{stage === 'done' ? '雷达已开启' : '分析并开启智能模式'}</Button><span className="form-footnote"><Check size={13} />仅处理公开内容，不自动发送消息</span></div></section><section className="panel workflow-panel"><PanelHeader label="AUTOMATION PLAN" title="系统将自动完成" /><div className="workflow-list">{['理解行业与客户语言', '生成高意图关键词', '发现并排序机会视频', '分析公开评论信号', '归档潜客并生成建议'].map((label, index) => <div className={`workflow-row ${stage && index < (stage === 'done' ? 5 : 2) ? 'complete' : ''}`} key={label}><span>{stage === 'done' || (stage && index < 2) ? <Check size={13} /> : String(index + 1).padStart(2, '0')}</span><b>{label}</b>{stage && index === 2 && stage !== 'done' && <i className="spinner" />}</div>)}</div>{result ? <div className="analysis-summary"><div className="summary-number">{result.keyword_count}</div><div><b>个行业关键词已生成</b><span>高机会词将优先进入扫描队列</span></div><div className="summary-tags">{Object.entries(result.categories || {}).slice(0, 6).map(([name, count]) => <span key={name}>{name} <b>{count as number}</b></span>)}</div></div> : <div className="workflow-note"><BrainIcon /><b>准备好后，系统会持续工作</b><span>你可以随时暂停任务、调整关键词或人工确认跟进建议。</span></div>}</section></div></div> }
function BrainIcon() { return <span className="brain-icon"><Bot size={22} /></span> }
function Field({ label, value, onChange, placeholder, wide, area }: RecordShape) { return <label className={`field ${wide ? 'wide' : ''}`}><span>{label}</span>{area ? <textarea value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} rows={3} /> : <input value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} />}</label> }

function KeywordsView({ project }: RecordShape) { const [items, setItems] = useState<RecordShape[]>([]); const [loading, setLoading] = useState(true); useEffect(() => { setLoading(true); request(`/api/projects/${project.id}/keywords`).then(setItems).catch(() => {}).finally(() => setLoading(false)) }, [project.id]); const rows = items.length ? items : demoKeywords; return <div className="page"><PageHeader eyebrow="OPPORTUNITY ENGINE" title="关键词雷达" description="让购买意图决定扫描优先级，而不是让关键词数量制造噪音。" actions={<><Button icon={SlidersHorizontal}>筛选</Button><Button variant="accent" icon={Plus}>添加关键词</Button></>} /><div className="kpi-strip"><div><b>{items.length || 50}</b><span>关键词总数</span></div><div><b>{rows.filter((item) => Number(item.opportunity_score) >= 90).length || 18}</b><span>高机会词</span></div><div><b>30%</b><span>购买意图权重</span></div><div className="kpi-note"><Zap size={15} /><span>高产出词会根据潜客历史自动加权</span></div></div><section className="panel data-panel"><div className="data-toolbar"><div className="filter-tabs"><button className="selected">全部 <small>{items.length || 50}</small></button><button>购买意向</button><button>痛点词</button><button>地域词</button><button>长尾词</button></div><div className="table-search"><Search size={14} />搜索关键词</div></div>{loading ? <TableSkeleton rows={5} /> : <table><thead><tr><th>关键词</th><th>类型</th><th>商业价值</th><th>机会评分</th><th>视频</th><th>评论</th><th>潜客</th><th>状态</th></tr></thead><tbody>{rows.map((item: RecordShape, index) => <tr key={item.id || item.keyword}><td><b>{item.keyword}</b><small>{item.reason || 'AI 推荐 · 需求语义明确'}</small></td><td><StatusPill tone={item.category === '购买意向' ? 'accent' : 'neutral'}>{item.category || '需求词'}</StatusPill></td><td><div className="mini-meter"><i style={{ width: `${item.commercial_score || 82}%` }} /></div><span className="meter-number">{item.commercial_score || 82}</span></td><td><span className={`score-value ${Number(item.opportunity_score) > 90 ? 'hot' : ''}`}>{Math.round(item.opportunity_score || 90)}</span></td><td>{item.video_count || 2 + index}</td><td>{item.comment_count || 18 + index * 8}</td><td><b className="accent-text">{item.lead_count || 12 + index}</b></td><td><span className="enabled"><i />已启用</span></td></tr>)}</tbody></table>}</section></div> }
function TableSkeleton({ rows }: { rows: number }) { return <div className="table-skeleton">{Array.from({ length: rows }, (_, index) => <div key={index}><Skeleton width="190px" /><Skeleton width="60px" /><Skeleton width="90px" /><Skeleton width="35px" /><Skeleton width="38px" /></div>)}</div> }

function VideosView({ project }: RecordShape) { const [items, setItems] = useState<RecordShape[]>([]); useEffect(() => { request(`/api/videos?project_id=${project.id}`).then(setItems).catch(() => {}) }, [project.id]); const rows = items.length ? items : demoVideos; return <div className="page"><PageHeader eyebrow="CONTENT RADAR" title="热门视频" description="用评论区的需求质量，判断哪些内容值得持续监控。" actions={<><Button icon={SlidersHorizontal}>筛选</Button><Button variant="accent" icon={RefreshCw}>扫描全部</Button></>} /><div className="video-toolbar"><div className="filter-tabs"><button className="selected">机会排序</button><button>最新发现</button><button>评论密度</button></div><span className="toolbar-meta"><span className="status-dot" />20 个视频正在监控</span></div><div className="video-list">{rows.map((item: RecordShape, index) => <article className="video-row" key={item.id || index}><div className={`video-thumb thumb-${index % 4}`}><span>DOUYIN</span><b>装修<br /><em>避坑指南</em></b><i>▶</i></div><div className="video-info"><div className="video-title-row"><h3>{item.title}</h3><StatusPill tone={item.level === 'A' ? 'accent' : 'neutral'}>{item.level || 'B'} 级机会</StatusPill></div><div className="video-source"><span className="creator-dot">{(item.creator || '长')[0]}</span>{item.creator || '长沙装修观察员'}<span>·</span><span>{item.keyword || '长沙装修避坑'}</span></div><div className="video-stats"><span>♡ {Number(item.likes || 12000).toLocaleString()}</span><span>◌ {item.comments || 80} 评论</span><span>发现潜客 <b>{item.lead_count || 12 + index}</b></span></div></div><div className="video-score"><span>机会评分</span><b>{Math.round(item.opportunity_score || 90)}</b><small>潜客密度 {item.lead_density || '16'}%</small></div><button className="row-more"><MoreHorizontal size={17} /></button></article>)}</div></div> }

function LeadDrawer({ lead, close, project, onUpdated }: RecordShape) {
  const [advice, setAdvice] = useState<RecordShape>()
  const [loading, setLoading] = useState(false)
  const [status, setStatus] = useState(lead.status || 'NEW')
  const [statusBusy, setStatusBusy] = useState(false)
  const [statusMessage, setStatusMessage] = useState('')
  const statuses: Record<string, string> = { NEW: '新发现', FOLLOW_UP: '待跟进', CONTACTED: '已联系', QUALIFIED: '有效客户', WON: '已成交', LOST: '未成交', IGNORED: '忽略' }
  useEffect(() => { setStatus(lead.status || 'NEW') }, [lead.id, lead.status])
  async function generate() { if (!lead.id || typeof lead.id !== 'number') return; setLoading(true); try { setAdvice(await request(`/api/leads/${lead.id}/persona`, { method: 'POST' })) } finally { setLoading(false) } }
  async function changeStatus(next: string) { setStatusBusy(true); setStatusMessage('保存中…'); try { const updated = await request(`/api/leads/${lead.id}`, { method: 'PATCH', body: JSON.stringify({ status: next }) }); setStatus(updated.status); onUpdated?.(updated); setStatusMessage('状态已更新') } catch (error: any) { setStatus(lead.status || 'NEW'); setStatusMessage(error.message) } finally { setStatusBusy(false) } }
  return <div className="drawer-backdrop" onClick={close}><aside className="lead-drawer" onClick={(event) => event.stopPropagation()}><div className="drawer-head"><span className="eyebrow">LEAD PROFILE</span><button className="icon-button" onClick={close}><X size={17} /></button></div><div className="drawer-identity"><span className="drawer-avatar">{(lead.nickname || '客')[0]}</span><div><h2>{lead.nickname}</h2><span>抖音用户 · {lead.platform_user_id || 'buyer-000'}</span></div><div className="drawer-score"><b>{Math.round(lead.lead_score || 90)}</b><small>{lead.lead_level || 'A'} 级</small></div></div><div className="drawer-status"><label htmlFor="lead-status">CRM 状态</label><select id="lead-status" className="select-control" value={status} onChange={(event) => void changeStatus(event.target.value)} disabled={statusBusy}>{Object.entries(statuses).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select>{statusMessage && <span>{statusMessage}</span>}</div><div className="drawer-facts"><div><span>需求</span><b>{lead.need || '旧房翻新 / 全屋装修'}</b></div><div><span>地区</span><b>{lead.location || project.location || '长沙'}</b></div><div><span>预算</span><b>{lead.budget || '待确认'}</b></div><div><span>阶段</span><b>{lead.purchase_stage || '比较方案'}</b></div></div><div className="drawer-section"><SectionLabel>AI SUMMARY</SectionLabel><p>{lead.summary || '客户正在认真了解装修方案，评论中出现明确需求与决策信号。'}</p></div><div className="drawer-section"><SectionLabel>BUYING SIGNALS</SectionLabel><div className="signal-tags">{(lead.buying_signals || ['明确询价', '表达真实需求', '关注本地服务']).map((signal: string) => <span key={signal}><Check size={12} />{signal}</span>)}</div></div><div className="drawer-section"><SectionLabel>COMMENT CONTEXT</SectionLabel>{lead.comments?.length ? <div className="history-list">{lead.comments.map((comment: RecordShape) => <div key={comment.id}><time>{formatDateTime(comment.created_at_platform || comment.created_at)}</time><p>{comment.content}</p></div>)}</div> : <p>暂无可展示的历史评论上下文。</p>}</div><div className="drawer-section"><SectionLabel>SOURCE VIDEOS</SectionLabel>{lead.videos?.length ? <div className="source-list">{lead.videos.map((video: RecordShape) => <a key={video.id} href={video.url || '#'} target="_blank" rel="noreferrer">{video.title || '无标题视频'} <ArrowUpRight size={12} /></a>)}</div> : <p>暂无来源视频记录。</p>}</div><div className="drawer-advice"><div className="drawer-advice-head"><div><SectionLabel>PERSONA AGENT</SectionLabel><b>人工跟进建议</b></div><Bot size={19} /></div>{advice ? <><blockquote>{advice.recommended_reply}</blockquote><p className="next-question"><b>下一问</b>{advice.follow_up_question}</p></> : <><p>生成一条专业、克制的回答建议，不会自动发送。</p><Button variant="accent" icon={Sparkles} onClick={generate} disabled={loading}>{loading ? '生成中…' : '生成跟进建议'}</Button></>}</div></aside></div>
}

function AgentsView() { const agents = [{ name: 'IndustryAgent', label: '行业理解', desc: '把业务描述整理成客户画像、痛点与搜索策略。', icon: BrainIcon, status: '已就绪' }, { name: 'KeywordAgent', label: '关键词发现', desc: '生成跨意图关键词并计算机会分，控制扫描顺序。', icon: Search, status: '已运行' }, { name: 'LeadJudgeAgent', label: '潜客判断', desc: '规则预筛后判断真实购买信号，减少无效 AI 调用。', icon: Target, status: '已运行' }, { name: 'PersonaAgent', label: '人设跟进', desc: '根据客户上下文生成仅供人工确认的跟进建议。', icon: MessageCircle, status: '待调用' }]; return <div className="page"><PageHeader eyebrow="AGENT SYSTEM" title="智能体" description="四个专注单一职责的 Agent，组成一条可观测的获客工作流。" actions={<Button icon={FileText}>查看运行记录</Button>} /><div className="agent-grid">{agents.map(({ name, label, desc, icon: Icon, status }) => <section className="panel agent-card" key={name}><div className="agent-card-top"><span className="agent-glyph"><Icon size={19} /></span><StatusPill tone={status === '待调用' ? 'neutral' : 'green'}>{status}</StatusPill></div><h2>{label}</h2><span className="agent-code">{name} · v1</span><p>{desc}</p><div className="agent-card-foot"><span><Activity size={13} />Mock fallback enabled</span><ChevronRight size={15} /></div></section>)}</div><section className="panel registry-panel"><div><SectionLabel>PROMPT REGISTRY</SectionLabel><h2>每次判断都可追踪</h2><p>记录 prompt version、输入哈希、耗时与输出，方便对比不同版本的真实效果。</p></div><div className="registry-numbers"><span><b>4</b>Agent 版本</span><span><b>128</b>本周运行</span><span><b>99%</b>成功率</span></div></section></div> }

function TasksView({ project }: RecordShape) {
  const [tasks, setTasks] = useState<RecordShape[]>([])
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)
  const refresh = async () => { try { setTasks(await request(`/api/tasks?project_id=${project.id}`)); setError('') } catch (err: any) { setError(err.message) } }
  useEffect(() => { void refresh() }, [project.id])
  const start = async () => { setBusy(true); try { await request(`/api/projects/${project.id}/scan`, { method: 'POST' }); await refresh() } catch (err: any) { setError(err.message) } finally { setBusy(false) } }
  const taskAction = async (task: RecordShape, action: 'pause' | 'resume' | 'retry') => { setBusy(true); try { await request(`/api/tasks/${task.id}/${action}`, { method: 'POST' }); await refresh() } catch (err: any) { setError(err.message) } finally { setBusy(false) } }
  return <div className="page"><PageHeader eyebrow="ORCHESTRATION" title="任务中心" description="每次扫描都能暂停、恢复、重试，并从 checkpoint 继续。" actions={<Button variant="accent" icon={Plus} onClick={start} disabled={busy}>{busy ? '提交中…' : '新建扫描'}</Button>} />{error && <div className="error-banner"><X size={15} />{error}</div>}<div className="task-grid"><section className="panel data-panel task-panel"><div className="data-toolbar"><div><SectionLabel>SCAN TASKS</SectionLabel><h2>扫描任务</h2></div><StatusPill tone="green">{tasks.length} 个任务</StatusPill></div>{tasks.length ? tasks.map((task: RecordShape) => <div className="task-item" key={task.id}><span className={`task-state ${task.status === 'completed' ? '' : 'pending'}`}>{task.status === 'completed' ? <Check size={14} /> : <Clock3 size={14} />}</span><div className="task-copy"><b>{task.name}</b><small>10 步 · 当前：{task.current_step || '等待启动'}</small></div><StatusPill tone={task.status === 'completed' ? 'green' : task.status === 'failed' ? 'red' : 'amber'}>{task.status === 'completed' ? '已完成' : task.status === 'queued' ? '排队中' : task.status === 'running' ? '运行中' : task.status === 'paused' ? '已暂停' : task.status === 'failed' ? '失败' : task.status}</StatusPill>{task.status === 'running' && <button className="icon-button" title="暂停" onClick={() => taskAction(task, 'pause')}><Pause size={16} /></button>}{task.status === 'paused' && <button className="icon-button" title="恢复" onClick={() => taskAction(task, 'resume')}><Play size={16} /></button>}{task.status === 'failed' && <button className="icon-button" title="重试" onClick={() => taskAction(task, 'retry')}><RefreshCw size={16} /></button>}</div>) : <EmptyState icon={ListChecks} text="还没有扫描任务，先创建一次扫描。" action={{ label: '创建扫描', onClick: start }} />}</section><section className="panel checkpoint-panel"><SectionLabel>RECOVERY STATE</SectionLabel><h2>断点续跑</h2><p>任务会持久化到数据库，API 重启后会重新排队继续执行。</p><div className="checkpoint-list"><div><span>执行方式</span><b>持久化 Worker</b></div><div><span>事件来源</span><b>数据库 + SSE</b></div><div><span>恢复策略</span><b>关键词级 checkpoint</b></div></div><div className="checkpoint-note"><Check size={14} />任务状态已持久化</div></section></div></div>
}

function AnalyticsView({ project }: RecordShape) { const [data, setData] = useState<RecordShape>({ levels: {} }); const [error, setError] = useState(''); useEffect(() => { request(`/api/analytics?project_id=${project.id}`).then(setData).catch((err) => setError(err.message)) }, [project.id]); const levels = data.levels || {}; return <div className="page"><PageHeader eyebrow="SIGNAL ANALYTICS" title="数据分析" description="从信号质量、关键词产出与 Provider 健康度看雷达效率。" actions={<Button icon={ArrowDownRight} onClick={() => downloadJson(`analytics-${project.id}.json`, data)}>导出报告</Button>} />{error && <div className="error-banner"><X size={15} />{error}</div>}<div className="analytics-grid"><section className="panel quality-panel"><PanelHeader label="LEAD QUALITY" title="潜客等级分布" action={<span className="muted">当前项目</span>} /><div className="quality-content"><div className="donut"><div><b>{Object.values(levels).reduce((sum: number, value: any) => sum + Number(value), 0)}</b><span>潜客总数</span></div></div><div className="legend-list">{Object.entries(levels).map(([level, value], index) => <div key={level}><i className={`legend-dot dot-${index}`} /><span>{level} 级</span><b>{value as number}</b></div>)}</div></div></section><section className="panel health-panel"><PanelHeader label="RADAR HEALTH" title="系统健康度" action={<StatusPill tone="green">稳定</StatusPill>} /><div className="health-number">98<small>/100</small></div><div className="health-bars"><HealthBar label="关键词覆盖" value={92} /><HealthBar label="评论覆盖" value={78} /><HealthBar label="判断成功率" value={99} /></div></section></div><section className="panel analytics-note"><Gauge size={18} /><div><b>下一步建议</b><span>优先复盘连续两轮无潜客的关键词，并把已转化客户的语言加入人群画像。</span></div><ArrowUpRight size={16} /></section></div> }
function HealthBar({ label, value }: RecordShape) { return <div><span>{label}</span><i><b style={{ width: `${value}%` }} /></i><strong>{value}%</strong></div> }

function LeadsView({ project }: RecordShape) {
  const [items, setItems] = useState<RecordShape[]>([])
  const [selected, setSelected] = useState<RecordShape>()
  const [error, setError] = useState('')
  useEffect(() => { request(`/api/leads?project_id=${project.id}`).then(setItems).catch((err) => setError(err.message)) }, [project.id])
  const openLead = async (lead: RecordShape) => { try { setSelected(await request(`/api/leads/${lead.id}`)) } catch (err: any) { setError(err.message); setSelected(lead) } }
  const updateSelected = (updated: RecordShape) => { setSelected((current) => ({ ...current, ...updated })); setItems((current) => current.map((item) => item.id === updated.id ? { ...item, ...updated } : item)) }
  return <div className="page"><PageHeader eyebrow="CUSTOMER SIGNALS" title="潜客池" description="把真实购买信号排成一条可以跟进的清晰队列。" actions={<Button icon={ArrowDownRight} onClick={() => downloadJson(`leads-${project.id}.json`, items)}>导出列表</Button>} />{error && <div className="error-banner"><X size={15} />{error}</div>}<div className="lead-tabs"><button className="active">全部 <b>{items.length}</b></button><button>S 级 <b>{items.filter((item) => item.lead_level === 'S').length}</b></button><button>A 级 <b>{items.filter((item) => item.lead_level === 'A').length}</b></button><button>待跟进 <b>{items.filter((item) => item.status === 'NEW').length}</b></button><div className="table-search"><Search size={14} />按评分排序</div></div><section className="panel data-panel lead-data">{items.length ? <table><thead><tr><th>潜客</th><th>评分</th><th>需求</th><th>位置 / 预算</th><th>摘要</th><th>出现</th><th>状态</th></tr></thead><tbody>{items.map((lead: RecordShape, index) => <tr key={lead.id} onClick={() => void openLead(lead)}><td><div className="lead-person"><span className={`lead-avatar lead-${index % 4}`}>{(lead.nickname || '客')[0]}</span><span><b>{lead.nickname}</b><small>抖音 · {lead.platform_user_id || '未知用户'}</small></span></div></td><td><span className={`lead-score score-${(lead.lead_level || 'A').toLowerCase()}`}>{Math.round(lead.lead_score || 0)} <small>{lead.lead_level || 'C'}</small></span></td><td><b>{lead.need || '待补充'}</b><small>{lead.pain_point || '暂无痛点'}</small></td><td><b>{lead.location || '待确认'}</b><small>{lead.budget || '预算待确认'}</small></td><td className="quote">{lead.summary || '暂无摘要'}</td><td><span className="occurrence">{lead.occurrence_count || 1} 次</span></td><td><StatusPill tone={lead.status === 'CONTACTED' ? 'blue' : 'green'}>{lead.status === 'CONTACTED' ? '已联系' : '待跟进'}</StatusPill></td></tr>)}</tbody></table> : <EmptyState icon={Target} text={error ? '无法加载真实潜客数据。' : '当前还没有潜客，完成一次扫描后会显示。'} />}</section>{selected && <LeadDrawer lead={selected} close={() => setSelected(undefined)} project={project} onUpdated={updateSelected} />}</div>
}

function ProvidersView() {
  const [items, setItems] = useState<RecordShape[]>([])
  const [active, setActive] = useState('')
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const refresh = async () => { setBusy(true); setError(''); try { const [providers, settings] = await Promise.all([request('/api/providers'), request('/api/settings')]); setItems(providers); setActive(settings.content_provider === 'mock' ? 'Mock Provider' : settings.content_provider || '') } catch (err: any) { setError(err.message) } finally { setBusy(false) } }
  useEffect(() => { void refresh() }, [])
  const health = async (provider: RecordShape) => { if (!provider.id) return; setBusy(true); setError(''); try { const result = await request(`/api/providers/${provider.id}/health`, { method: 'POST' }); setItems((current) => current.map((item) => item.id === result.id ? result : item)) } catch (err: any) { setError(err.message) } finally { setBusy(false) } }
  const activate = async (provider: RecordShape) => { if (!provider.id) return; setBusy(true); setError(''); try { const result = await request(`/api/providers/${provider.id}/activate`, { method: 'POST' }); setActive(result.active); setItems((current) => current.map((item) => item.id === result.provider.id ? result.provider : item)) } catch (err: any) { setError(err.message) } finally { setBusy(false) } }
  return <div className="page"><PageHeader eyebrow="PROVIDER LAYER" title="数据源" description="采集工具可以替换，AI、任务与潜客模型不随平台变化。" actions={<Button icon={RefreshCw} onClick={refresh} disabled={busy}>{busy ? '处理中…' : '检测全部'}</Button>} />{error && <div className="error-banner"><X size={15} />{error}</div>}<div className="provider-grid">{items.map((provider: RecordShape, index) => <section className="panel provider-card" key={provider.id || provider.name}><div className="provider-card-head"><span className={`provider-mark provider-${index}`}><Database size={18} /></span><StatusPill tone={active === provider.name || provider.status === 'connected' && provider.name === 'Mock Provider' ? 'green' : 'neutral'}>{active === provider.name ? 'Active' : provider.status === 'connected' ? 'Connected' : 'Disconnected'}</StatusPill></div><h2>{provider.name}</h2><p>{provider.note}</p>{provider.endpoint && <code>{provider.endpoint}</code>}<div className="capability-list">{Object.entries(provider.capabilities || {}).map(([key, value]) => <span className={value ? 'on' : ''} key={key}><i />{key.replace('_', ' ')}</span>)}</div><div className="provider-actions"><Button variant="secondary" icon={Wifi} onClick={() => health(provider)} disabled={busy}>检测服务</Button><Button variant={active === provider.name ? 'secondary' : 'accent'} onClick={() => activate(provider)} disabled={busy || active === provider.name}>{active === provider.name ? '当前使用' : '启用此数据源'}</Button></div></section>)}</div>{!items.length && !error && <EmptyState icon={Database} text="正在加载数据源…" />}<div className="compliance-bar"><Check size={15} /><span><b>边界声明：</b>外部采集器由用户独立运行并自行确认平台规则与许可证；本系统只处理公开内容和人工跟进辅助。</span></div></div>
}

function SettingsView({ project }: RecordShape) {
  const [form, setForm] = useState<RecordShape>({ llm_base_url: '', llm_api_key: '', llm_model: 'deepseek-chat', llm_temperature: '0.2', llm_timeout: '45' })
  const [schedule, setSchedule] = useState<RecordShape>({ enabled: false, interval_minutes: 180, full: false, next_run_at: null, last_run_at: null })
  const [status, setStatus] = useState('')
  const [scheduleStatus, setScheduleStatus] = useState('')
  const [testing, setTesting] = useState(false)
  const [scheduleBusy, setScheduleBusy] = useState(false)
  const refresh = async () => {
    const [settings, scheduleData] = await Promise.all([request('/api/settings'), request(`/api/projects/${project.id}/schedule`)] )
    setForm((current) => ({ ...current, ...settings, llm_temperature: String(settings.llm_temperature ?? current.llm_temperature), llm_timeout: String(settings.llm_timeout ?? current.llm_timeout), llm_api_key: '' }))
    setSchedule(scheduleData)
  }
  useEffect(() => { void refresh().catch(() => {}) }, [project.id])
  function set(key: string, value: string) { setForm((current) => ({ ...current, [key]: value })) }
  function setScheduleValue(key: string, value: unknown) { setSchedule((current) => ({ ...current, [key]: value })) }
  async function save() { setStatus('保存中…'); try { await request('/api/settings', { method: 'PUT', body: JSON.stringify(form) }); setStatus('已保存，后续 Agent 将使用文本模型配置。') } catch (error: any) { setStatus(error.message) } }
  async function saveSchedule() { setScheduleBusy(true); setScheduleStatus('保存中…'); try { const result = await request(`/api/projects/${project.id}/schedule`, { method: 'PUT', body: JSON.stringify({ enabled: Boolean(schedule.enabled), interval_minutes: Number(schedule.interval_minutes), full: Boolean(schedule.full) }) }); setSchedule(result); setScheduleStatus(result.enabled ? '已启用自动扫描' : '自动扫描已暂停') } catch (error: any) { setScheduleStatus(error.message) } finally { setScheduleBusy(false) } }
  async function test() { setTesting(true); setStatus('测试连接中…'); try { const result = await request('/api/settings/test-llm', { method: 'POST', body: JSON.stringify(form) }); setStatus(result.message) } catch (error: any) { setStatus(error.message) } finally { setTesting(false) } }
  const intervalOptions = [[15, '每 15 分钟'], [30, '每 30 分钟'], [60, '每 1 小时'], [180, '每 3 小时'], [360, '每 6 小时'], [720, '每 12 小时'], [1440, '每天'], [10080, '每 7 天']]
  return <div className="page"><PageHeader eyebrow="WORKSPACE SETTINGS" title="系统设置" description="管理文本模型、项目扫描计划和工作区偏好。" actions={<Button variant="accent" onClick={save}>保存更改</Button>} /><div className="settings-stack"><section className="panel text-model-settings"><div className="settings-heading"><div><SectionLabel>TEXT MODEL</SectionLabel><h2>文本模型配置</h2><p>行业理解、关键词、潜客判断和人设建议均通过文字与结构化字段完成。</p></div><StatusPill tone="green">{form.llm_api_key_configured ? '已配置' : 'Mock fallback'}</StatusPill></div><div className="settings-form-grid"><Field label="Base URL" value={form.llm_base_url || ''} onChange={(value: string) => set('llm_base_url', value)} placeholder="https://api.example.com/v1" /><Field label="API Key" value={form.llm_api_key || ''} onChange={(value: string) => set('llm_api_key', value)} placeholder={form.llm_api_key_configured ? '已保存，留空保持不变' : 'sk-…'} /><Field label="Model" value={form.llm_model || ''} onChange={(value: string) => set('llm_model', value)} placeholder="deepseek-chat" /><Field label="Temperature" value={String(form.llm_temperature ?? '')} onChange={(value: string) => set('llm_temperature', value)} placeholder="0.2" /><Field label="Timeout (seconds)" value={String(form.llm_timeout ?? '')} onChange={(value: string) => set('llm_timeout', value)} placeholder="45" /></div><div className="settings-actions"><Button icon={Wifi} onClick={test} disabled={testing}>{testing ? '测试中…' : '测试连接'}</Button>{status && <span className="settings-status"><span className="status-dot" />{status}</span>}</div></section><SettingRow title="扫描频率" desc="启用后，系统会按项目计划自动排队扫描；有任务运行时不会重复入队。" action={<div className="schedule-controls"><label className="schedule-toggle"><input type="checkbox" checked={Boolean(schedule.enabled)} onChange={(event) => setScheduleValue('enabled', event.target.checked)} /><span>自动运行</span></label><select className="select-control" value={String(schedule.interval_minutes)} onChange={(event) => setScheduleValue('interval_minutes', Number(event.target.value))}>{intervalOptions.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select><Button onClick={saveSchedule} disabled={scheduleBusy}>{scheduleBusy ? '保存中…' : '保存计划'}</Button></div>} /><div className="schedule-meta"><span>{schedule.enabled ? `下次运行：${formatDateTime(schedule.next_run_at)}` : '计划未启用'}</span>{schedule.last_run_at && <span>上次运行：{formatDateTime(schedule.last_run_at)}</span>}{scheduleStatus && <span className="settings-status"><span className="status-dot" />{scheduleStatus}</span>}</div><SettingRow title="人工跟进保护" desc="所有 PersonaAgent 输出都只是建议，不会自动发送或触达客户。" action={<StatusPill tone="blue">已启用</StatusPill>} /></div></div>
}
function SettingRow({ title, desc, action }: RecordShape) { return <div className="panel setting-row"><div><h2>{title}</h2><p>{desc}</p></div>{action}</div> }

function KeywordsViewLive({ project }: RecordShape) {
  const [items, setItems] = useState<RecordShape[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [category, setCategory] = useState('全部')
  const [query, setQuery] = useState('')
  const reload = async () => { setLoading(true); try { setItems(await request(`/api/projects/${project.id}/keywords`)); setError('') } catch (err: any) { setError(err.message) } finally { setLoading(false) } }
  useEffect(() => { void reload() }, [project.id])
  const categories = ['全部', '购买意向', '痛点词', '地域词', '长尾词']
  const rows = items.filter((item) => (category === '全部' || item.category === category) && (!query.trim() || String(item.keyword).includes(query.trim())))
  const toggle = async (item: RecordShape) => { try { const updated = await request(`/api/keywords/${item.id}?enabled=${!item.enabled}`, { method: 'PATCH' }); setItems((current) => current.map((row) => row.id === item.id ? updated : row)) } catch (err: any) { setError(err.message) } }
  return <div className="page"><PageHeader eyebrow="OPPORTUNITY ENGINE" title="关键词雷达" description="让购买意图决定扫描优先级，而不是让关键词数量制造噪音。" actions={<span className="provider-chip">{items.length} 个文本关键词</span>} />{error && <div className="error-banner"><X size={15} />{error}</div>}<div className="kpi-strip"><div><b>{items.length}</b><span>关键词总数</span></div><div><b>{items.filter((item) => Number(item.opportunity_score) >= 90).length}</b><span>高机会词</span></div><div><b>{items.length ? Math.round(items.reduce((sum, item) => sum + Number(item.commercial_score || 0), 0) / items.length) : 0}</b><span>平均商业价值</span></div><div className="kpi-note"><Zap size={15} /><span>数据来自当前项目，不使用演示回退</span></div></div><section className="panel data-panel"><div className="data-toolbar"><div className="filter-tabs">{categories.map((item) => <button key={item} className={category === item ? 'selected' : ''} onClick={() => setCategory(item)}>{item}</button>)}</div><input className="table-search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="搜索关键词" /></div>{loading ? <TableSkeleton rows={5} /> : rows.length ? <table><thead><tr><th>关键词</th><th>类型</th><th>商业价值</th><th>机会评分</th><th>视频</th><th>评论</th><th>潜客</th><th>状态</th></tr></thead><tbody>{rows.map((item: RecordShape, index) => <tr key={item.id}><td><b>{item.keyword}</b><small>{item.reason || '文本模型推荐'}</small></td><td><StatusPill tone={item.category === '购买意向' ? 'accent' : 'neutral'}>{item.category}</StatusPill></td><td><div className="mini-meter"><i style={{ width: `${item.commercial_score || 0}%` }} /></div><span className="meter-number">{Math.round(item.commercial_score || 0)}</span></td><td><span className={`score-value ${Number(item.opportunity_score) > 90 ? 'hot' : ''}`}>{Math.round(item.opportunity_score || 0)}</span></td><td>{item.video_count || 0}</td><td>{item.comment_count || 0}</td><td><b className="accent-text">{item.lead_count || 0}</b></td><td><button className="enabled" onClick={() => toggle(item)}><i />{item.enabled ? '已启用' : '已停用'}</button></td></tr>)}</tbody></table> : <EmptyState icon={Radar} text={error ? '无法加载真实关键词。' : '当前项目还没有关键词，请先运行智能截流。'} />}</section></div>
}

function VideosViewLive({ project }: RecordShape) {
  const [items, setItems] = useState<RecordShape[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)
  const [sort, setSort] = useState('机会排序')
  const reload = async () => { setLoading(true); try { setItems(await request(`/api/videos?project_id=${project.id}`)); setError('') } catch (err: any) { setError(err.message) } finally { setLoading(false) } }
  useEffect(() => { void reload() }, [project.id])
  const scan = async () => { setBusy(true); try { await request(`/api/projects/${project.id}/scan?full=true`, { method: 'POST' }); await reload() } catch (err: any) { setError(err.message) } finally { setBusy(false) } }
  const rows = [...items].sort((a, b) => sort === '最新发现' ? String(b.discovered_at || '').localeCompare(String(a.discovered_at || '')) : sort === '评论密度' ? Number(b.comments || 0) - Number(a.comments || 0) : Number(b.opportunity_score || 0) - Number(a.opportunity_score || 0))
  return <div className="page"><PageHeader eyebrow="CONTENT RADAR" title="热门视频" description="只依据标题、描述、作者和公开互动数据判断机会，不读取画面。" actions={<Button variant="accent" icon={RefreshCw} onClick={scan} disabled={busy}>{busy ? '扫描排队中…' : '扫描全部'}</Button>} />{error && <div className="error-banner"><X size={15} />{error}</div>}<div className="video-toolbar"><div className="filter-tabs">{['机会排序', '最新发现', '评论密度'].map((item) => <button key={item} className={sort === item ? 'selected' : ''} onClick={() => setSort(item)}>{item}</button>)}</div><span className="toolbar-meta"><span className="status-dot" />{items.length} 个真实视频记录</span></div>{loading ? <TableSkeleton rows={6} /> : rows.length ? <div className="video-list">{rows.map((item: RecordShape, index) => <article className="video-row" key={item.id}><div className={`video-thumb thumb-${index % 4}`}><span>TEXT / META</span><b>{item.level || 'C'}<br /><em>机会记录</em></b><i>↗</i></div><div className="video-info"><div className="video-title-row"><h3>{item.title || '无标题视频'}</h3><StatusPill tone={item.level === 'A' || item.level === 'S' ? 'accent' : 'neutral'}>{item.level || 'C'} 级机会</StatusPill></div><div className="video-source"><span className="creator-dot">{(item.creator || '匿')[0]}</span>{item.creator || '未知作者'}<span>·</span><span>{item.keyword || '未关联关键词'}</span></div><div className="video-stats"><span>赞 {Number(item.likes || 0).toLocaleString()}</span><span>评论 {Number(item.comments || 0).toLocaleString()}</span><span>收藏 {Number(item.collects || 0).toLocaleString()}</span></div></div><div className="video-score"><span>机会评分</span><b>{Math.round(item.opportunity_score || 0)}</b><small>行业相关度 {Math.round(item.industry_relevance_score || 0)}%</small></div></article>)}</div> : <EmptyState icon={Video} text={error ? '无法加载真实视频。' : '当前还没有视频记录，请先执行扫描。'} />}</div>
}
